// Draw world markers as billboard rings.
for(let z of redZones){let dx=z.x-player.x,dy=z.y-player.y,dist=Math.hypot(dx,dy),rel=Math.atan2(dy,dx)-player.a;while(rel>Math.PI)rel-=Math.PI*2;while(rel<-Math.PI)rel+=Math.PI*2;if(Math.abs(rel)>.75||dist<.7)continue;let sx=(W/2+Math.tan(rel)*PROJ)*scale,sy=ch*.66*scale,size=Math.max(2,PROJ/dist*.52)*scale;if(dist>zbuf[Math.max(0,Math.min(W-1,Math.round(sx/scale)))])continue;ctx.save();ctx.translate(sx,sy);ctx.strokeStyle=zoneActive&&pulseSilence<=0?'rgba(255,48,81,.78)':'rgba(72,229,203,.34)';ctx.lineWidth=2*scale;ctx.shadowColor=zoneActive&&pulseSilence<=0?'#ff3157':'#49e5eb';ctx.shadowBlur=14*scale;ctx.beginPath();ctx.ellipse(0,0,size*1.6,size*.42,0,0,Math.PI*2);ctx.stroke();ctx.restore()}
