function update(dt){elapsed+=dt;player.fireCd=Math.max(0,player.fireCd-dt);player.pulseCd=Math.max(0,player.pulseCd-dt);player.damageCd=Math.max(0,player.damageCd-dt);player.dashCd=Math.max(0,player.dashCd-dt);player.dash=Math.max(0,player.dash-dt);weaponKick=Math.max(0,weaponKick-dt*3);shotFlash=Math.max(0,shotFlash-dt*8);flash=Math.max(0,flash-dt*2.7);pulseSilence=Math.max(0,pulseSilence-dt);player.energy=Math.min(100,player.energy+dt*3.2);
