}
function movePlayer(dx,dy){let r=.22;if(!wallAt(player.x+dx+Math.sign(dx)*r,player.y))player.x+=dx;if(!wallAt(player.x,player.y+dy+Math.sign(dy)*r))player.y+=dy}
