function shoot(){if(player.fireCd>0)return;player.fireCd=.19;shotFlash=.9;weaponKick=1;let target=null,nearest=10;for(const e of enemies){if(!e.alive)continue;let dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),rel=Math.atan2(dy,dx)-player.a;while(rel>Math.PI)rel-=Math.PI*2;while(rel<-Math.PI)rel+=Math.PI*2;let aimWidth=Math.atan((e.type==='brute'?.43:.34)/Math.max(.5,d));if(Math.abs(rel)<aimWidth+.012&&d<nearest&&clearSight(player.x,player.y,e.x,e.y)){target=e;nearest=d}}if(target){target.hp-=48;target.stun=Math.max(target.stun,.12);showMessage(target.hp<=0?'GRAFT SEVERED':'SIGNAL HIT',.35);if(target.hp<=0){target.alive=false;player.kills++;player.energy=Math.min(100,player.energy+16);for(let i=0;i<18;i++)blood.push({x:.42+Math.random()*.16,y:.38+Math.random()*.22,r:.004+Math.random()*.013,life:.65+Math.random()*.65});if(player.kills===enemies.length)showMessage('THE CORE IS EXPOSED',1.2)}}else{showMessage('MISS',.18)}syncHud()}
