function startGame(){reset();running=true;paused=false;$('overlay').classList.add('hidden');$('start').textContent='ENTER THE CATHEDRAL  →';last=performance.now();if(matchMedia('(pointer:fine)').matches&&canvas.requestPointerLock)canvas.requestPointerLock();requestAnimationFrame(loop)}
function loop(now){if(!running)return;let dt=Math.min(.045,(now-last)/1000||0);last=now;if(!paused)update(dt);render();if(paused){ctx.fillStyle='rgba(0,0,0,.58)';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#ccff45';ctx.textAlign='center';ctx.font='bold 34px sans-serif';ctx.fillText('PAUSED',canvas.width/2,canvas.height/2)}if(msgTimer>0){msgTimer-=dt;if(msgTimer<=0)$('message').classList.remove('show')}requestAnimationFrame(loop)}

