const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true});
 const page=await browser.newPage({viewport:{width:1280,height:800}});
 const errors=[]; page.on('pageerror', e=>errors.push(e.message)); page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 await page.goto('http://localhost:3002'); await page.locator('#start').click();
 await page.waitForTimeout(600);
 const started=await page.locator('#overlay').evaluate(e=>e.classList.contains('hidden'));
 await page.keyboard.press('q'); await page.waitForTimeout(100);
 const pulse=await page.locator('#energyNum').textContent();
 await page.keyboard.down('w'); await page.waitForTimeout(500); await page.keyboard.up('w');
 await page.locator('#view').evaluate(el=>el.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,button:0,pointerType:'mouse'})));
 await page.waitForTimeout(400);
 await page.keyboard.press('Escape'); await page.waitForTimeout(50);
 const result={started,pulse,health:await page.locator('#healthNum').textContent(),kills:await page.locator('#kills').textContent(),status:await page.locator('#status').textContent(),errors,dimensions:await page.locator('#view').evaluate(e=>[e.width,e.height])};
 console.log(JSON.stringify(result,null,2)); await browser.close();
})();
